using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class ActorFileImportOperations:RefCounted
{
    private readonly ActorDataOperations _data=new();private readonly ActorDefinitionOperations _definitions=new();
    private static readonly HashSet<string> Videos=new(StringComparer.Ordinal){"mp4","mov","mkv","webm","avi","m4v","ogv","mpeg","mpg","wmv","ts"};
    private static bool Script(Resource? resource,string path)=>ActorDataOperations.ScriptIs(resource,path);
    public StringName type_for_path(string path)
    {
        var picker=GD.Load<GDScript>("res://scripts/actors/core/actor_project_file_picker.gd");if(!picker.Call("is_allowed_path",picker.Call("root_directory"),path,Array.Empty<string>()).AsBool())return new StringName("");string extension=path.GetExtension().ToLowerInvariant();if(Videos.Contains(extension))return new StringName("video");if(extension is "mp3" or "wav" or "ogg" or "flac")return new StringName("audio");if(extension is "glb" or "gltf" or "fbx" or "obj" or "dae" or "blend" or "mesh")return new StringName("basic_mesh");if(extension is "png" or "jpg" or "jpeg" or "webp" or "bmp" or "svg" or "tga" or "exr" or "hdr")return new StringName("image_3d");if(extension is not ("tres" or "res"))return new StringName("");var resource=ResourceLoader.Load(path);if(Script(resource,"res://scripts/actors/core/actor_scene_data.gd"))return new StringName("scene_instance");if(Script(resource,"res://Workspaces/ModelWorkspace/model_document.gd"))return new StringName("basic_mesh");if(Script(resource,"res://Workspaces/TransformationWorkspace/transformation_document.gd"))return new StringName("transform_image_2d");if(Script(resource,"res://scripts/actors/core/actor_object_data.gd")){string type=resource.Get("type_id").AsString();if(type=="text_settings")return new StringName("text_3d");if(type=="environment")return new StringName("world_environment");if(type is "image" or "noise_image")return new StringName("image_3d");}return new StringName(resource switch{Godot.Environment=>"world_environment",Mesh or PackedScene=>"basic_mesh",Texture2D=>"image_3d",AudioStream=>"audio",_=>""});
    }
    public double scene_duration(Resource? scene){if(scene==null||scene.Get("clips").AsGodotArray().Count==0)return 5;double first=double.PositiveInfinity,last=double.NegativeInfinity;foreach(var value in scene.Get("clips").AsGodotArray()){var clip=value.As<Resource>();first=Math.Min(first,clip.Get("start_time").AsDouble());last=Math.Max(last,clip.Get("start_time").AsDouble()+clip.Get("duration").AsDouble());}return Math.Max(.1,last-first);}
    public Settings values_for_path(string path,RefCounted registry)
    {
        string type=type_for_path(path).ToString(),extension=path.GetExtension().ToLowerInvariant();var resource=extension is "tres" or "res"?ResourceLoader.Load(path):null;switch(type){case "transform_image_2d":return new Settings{[new StringName("transformation")]=path};case "text_3d":return new Settings{[new StringName("text_settings")]=_data.from_asset(path,new StringName("text_settings"))};case "video":return new Settings{[new StringName("video")]=path};case "audio":return new Settings{[new StringName("audio")]=resource is AudioStream?Variant.From(resource):Variant.From(path)};case "basic_mesh":return new Settings{[new StringName("mesh_path")]=path};case "image_3d":if(Script(resource,"res://scripts/actors/core/actor_object_data.gd"))return new Settings{[new StringName("image_path")]=_data.from_asset(path,resource!.Get("type_id").AsStringName())};var image=_definitions.create_object(_definitions.get_object_definition(registry,new StringName("image"))!);_data.set_value(image,new StringName("source"),resource is Texture2D?Variant.From(resource):Variant.From(path));return new Settings{[new StringName("image_path")]=_data.from_object(image)};case "world_environment":if(Script(resource,"res://scripts/actors/core/actor_object_data.gd"))return new Settings{[new StringName("environment")]=_data.from_asset(path,new StringName("environment"))};if(resource is Godot.Environment environment)return new Settings{[new StringName("environment")]=_data.from_object(environment_from_native(environment,registry))};break;}return new Settings();
    }
    public Resource environment_from_native(Godot.Environment native,RefCounted registry)
    {
        var result=_definitions.create_object(_definitions.get_object_definition(registry,new StringName("environment"))!);var aliases=new Dictionary<string,string>{{"ambient_source","ambient_light_source"},{"ambient_color","ambient_light_color"},{"ambient_energy","ambient_light_energy"},{"ambient_sky_contribution","ambient_light_sky_contribution"},{"reflected_source","reflected_light_source"},{"tone_mapper","tonemap_mode"},{"exposure","tonemap_exposure"},{"white_point","tonemap_white"},{"fog_color","fog_light_color"},{"background_energy","background_energy_multiplier"}};var names=new HashSet<string>();foreach(var property in native.GetPropertyList())names.Add(property["name"].AsString());var values=result.Get("values").AsGodotDictionary();foreach(var key in values.Keys){string name=aliases.TryGetValue(key.AsString(),out string? alias)?alias:key.AsString();if(key.AsString()!="background_mode"&&names.Contains(name))values[key]=native.Get(name);}values[new StringName("background_mode")]=0;if(native.BackgroundMode!=Godot.Environment.BGMode.Sky||native.Sky==null)return result;
        switch(native.Sky.SkyMaterial){case PanoramaSkyMaterial panorama:values[new StringName("background_mode")]=1;values[new StringName("background_image")]=panorama.Panorama;break;case ProceduralSkyMaterial procedural:values[new StringName("background_mode")]=2;foreach(string key in new[]{"sky_top_color","sky_horizon_color","sky_curve","ground_bottom_color","ground_horizon_color","ground_curve","sun_angle_max","sun_curve"})values[new StringName(key)]=procedural.Get(key);values[new StringName("sky_energy")]=procedural.SkyEnergyMultiplier;values[new StringName("ground_energy")]=procedural.GroundEnergyMultiplier;values[new StringName("sky_debanding")]=procedural.UseDebanding;break;case ShaderMaterial shader:values[new StringName("background_mode")]=3;var material=_definitions.create_object(_definitions.get_object_definition(registry,new StringName("shader_material"))!);var settings=material.Get("values").AsGodotDictionary();settings[new StringName("shader")]=shader.Shader;var uniforms=new Settings();if(shader.Shader!=null)foreach(var uniform in shader.Shader.GetShaderUniformList()){var name=uniform.AsGodotDictionary()["name"].AsStringName();uniforms[name]=shader.GetShaderParameter(name);}settings[new StringName("uniforms")]=uniforms;values[new StringName("sky_material")]=_data.from_object(material);break;}return result;
    }
    public bool register_catalog(Resource catalog,RefCounted registry){foreach(var value in catalog.Get("object_definitions").AsGodotArray())if(!_definitions.register_object(registry,value.As<Resource>()))return false;foreach(var value in catalog.Get("definitions").AsGodotArray())if(!_definitions.register(registry,value.As<Resource>()))return false;return true;}
}
